// TODO consider using Option(T) instead of data/valid
pub interface axi_stream(T: type) {
    data: T,
    valid: bool,
    ready: bool,

    view input {
        data: in,
        valid: in,
        ready: out,
    }

    view output {
        data: out,
        valid: out,
        ready: in,
    }
}

pub module axi_passthrough(T: type) ports(
    clk: in clock,
    rst: in async bool,
    input: interface sync(clk, async rst) axi_stream(T).input,
    output: interface sync(clk, async rst) axi_stream(T).output,
) {
    comb {
        output.data = input.data;
        output.valid = input.valid;
        input.ready = output.ready;
    }
}

pipeline_src:
// TODO expand this into an axi pipeline module, with real backpressure and valid so the undef resets don't leak out
pub module pipeline(N: uint, T: [N + 1]type, F: [N]any) ports(
    clk: in clock,
    x: in sync(clk) T[0],
    y: out sync(clk) T[N - 1],
) {
    wire v_0: T[0] = x;

    for (i in 0..N) {
        const id_prev = "v_{i}";
        const id_next = "v_{i + 1}";

        pub wire ident(id_next): T[i];

        clocked(clk) {
            reg wire ident(id_next) = undef;
            ident(id_next) = (F[i])(ident(id_prev));
        }
    }

    comb {
        y = ident("v_{N}");
    }
}

const {
    fn f(x: any) -> any {
        return !x;
    }
    pipeline(1, [bool, bool], [f]);
}

